  // GROUP 1: Basic Rendering
  // ==========================================================================
  describe('Basic Rendering', () => {
    test('renders without crashing', () => {
      render(<Header title="Test Title" status="Operational" />);
      expect(screen.getByRole('banner')).toBeInTheDocument();
    });

    test('renders the provided title correctly', () => {
      const testTitle = 'System Dashboard';
      render(<Header title={testTitle} status="Operational" />);
      expect(screen.getByRole('heading', { level: 1 })).toHaveTextContent(testTitle);
    });

    test('renders the system status label', () => {
      render(<Header title="Test" status="Operational" />);
      expect(screen.getByText('System Status:')).toBeInTheDocument();
    });

    test('renders the status text', () => {
      render(<Header title="Test" status="Degraded" />);
      expect(screen.getByText('Degraded')).toBeInTheDocument();
    });
  });

  // ==========================================================================
