  describe('Status Color Logic', () => {
    test('applies success color class when status is "Operational"', () => {
      render(<Header title="Test" status="Operational" />);
      const statusDot = document.querySelector('.bg-swarm-success');
      expect(statusDot).toBeInTheDocument();
      expect(statusDot).not.toHaveClass('bg-swarm-danger');
    });

    test('applies danger color class when status is not "Operational"', () => {
      const nonOperationalStatuses = ['Degraded', 'Down', 'Maintenance', 'Unknown', ''];

      nonOperationalStatuses.forEach((status) => {
        cleanup();
        render(<Header title="Test" status={status} />);
        const statusDot = document.querySelector('.bg-swarm-danger');
        expect(statusDot).toBeInTheDocument();
        expect(statusDot).not.toHaveClass('bg-swarm-success');
      });
    });

    test('handles undefined status by applying danger class (defensive)', () => {
      render(<Header title="Test" />);
      expect(document.querySelector('.bg-swarm-danger')).toBeInTheDocument();
    });

    test('handles null status by applying danger class (defensive)', () => {
      render(<Header title="Test" status={null} />);
      expect(document.querySelector('.bg-swarm-danger')).toBeInTheDocument();
    });
  });

